select t.device_code, t.access_node from vm_device_info_t t inner join vm_order_devices o on t.device_code = o.device_code where o.tenant_id = #{param.tenantId} and o.industry_code = #{param.industryCode} and o.ord_status in (0,1,2) and o.delete_flag = 0 and t.delete_flag = 0 and t.device_code in
#{item}
